        internal uint decode(uint _ft)
        {
            uint s;
            this.ext = this.rng / _ft;
            s = (uint)(this.val / this.ext);
            return _ft - Inlines.EC_MINI(s + 1, _ft);
        }

        internal uint decode_bin(uint _bits)
        {
            uint s;
            this.ext = this.rng >> (int)_bits;
            s = (uint)(this.val / this.ext);
            return (1U << (int)_bits) - Inlines.EC_MINI(s + 1U, 1U << (int)_bits);
        }

        internal void dec_update(uint _fl, uint _fh, uint _ft)
        {
            uint s;
            s = this.ext * (_ft - _fh);
            this.val -= s;
            this.rng = _fl > 0 ? this.ext * (_fh - _fl) : this.rng - s;
            dec_normalize();
        }

        /// <summary>
        /// The probability of having a "one" is 1/(1&lt;&lt;_logp).
        /// </summary>
        /// <param name="_logp"></param>
        /// <returns></returns>
        internal int dec_bit_logp(uint _logp)
        {
            uint r;
            uint d;
            uint s;
            int ret;
            r = this.rng;
            d = this.val;
            s = r >> (int)_logp;
            ret = d < s ? 1 : 0;
            if (ret == 0) this.val = d - s;
            this.rng = ret != 0 ? s : r - s;
            dec_normalize();
            return ret;
        }

        internal int dec_icdf(byte[] _icdf, uint _ftb)
        {
            uint r;
            uint d;
            uint s;
            uint t;
            int ret;
            s = this.rng;
            d = this.val;
            r = s >> (int)_ftb;
            ret = -1;
            do
            {
                t = s;
                s = r * _icdf[++ret];
            }
            while (d < s);
            this.val = d - s;
            this.rng = t - s;
            dec_normalize();
            return ret;
        }

        internal int dec_icdf(byte[] _icdf, int _icdf_offset, uint _ftb)
        {
            uint r;
            uint d;
            uint s;
            uint t;
            int ret;
            s = this.rng;
            d = this.val;
            r = s >> (int)_ftb;
            ret = _icdf_offset - 1;
            do
            {
                t = s;
                s = r * _icdf[++ret];
            }
            while (d < s);
            this.val = d - s;
            this.rng = t - s;
            dec_normalize();
            return ret - _icdf_offset;
        }

        internal uint dec_uint(uint _ft)
        {
            uint ft;
            uint s;
            int ftb;
            /*In order to optimize EC_ILOG(), it is undefined for the value 0.*/
            Inlines.OpusAssert(_ft > 1);
            _ft--;
            ftb = Inlines.EC_ILOG(_ft);
            if (ftb > EC_UINT_BITS)
            {
                uint t;
                ftb -= EC_UINT_BITS;
                ft = (uint)(_ft >> ftb) + 1;
                s = decode(ft);
                dec_update(s, s + 1, ft);
                t = (uint)s << ftb | dec_bits((uint)ftb);
                if (t <= _ft) return t;
                this.error = 1;
                return _ft;
            }
            else {
                _ft++;
                s = decode((uint)_ft);
                dec_update(s, s + 1, (uint)_ft);
                return s;
            }
        }

        internal uint dec_bits(uint _bits)
        {
            uint window;
            int available;
            uint ret;
            window = this.end_window;
            available = this.nend_bits;
            if ((uint)available < _bits)
            {
                do
                {
                    window |= (uint)read_byte_from_end() << available;
                    available += EC_SYM_BITS;
                }
                while (available <= EC_WINDOW_SIZE - EC_SYM_BITS);
            }
            ret = (uint)window & (((uint)1 << (int)_bits) - 1U);
            window = window >> (int)_bits;
            available = available - (int)_bits;
            this.end_window = window;
            this.nend_bits = available;
            this.nbits_total = this.nbits_total + (int)_bits;
            return ret;
        }

        /// <summary>
        /// Outputs a symbol, with a carry bit.
        /// If there is a potential to propagate a carry over several symbols, they are
        /// buffered until it can be determined whether or not an actual carry will
        /// occur.
        /// If the counter for the buffered symbols overflows, then the stream becomes
        /// undecodable.
        /// This gives a theoretical limit of a few billion symbols in a single packet on
        /// 32-bit systems.
        /// The alternative is to truncate the range in order to force a carry, but
        /// requires similar carry tracking in the decoder, needlessly slowing it down.
        /// </summary>
        /// <param name="_c"></param>
        internal void enc_carry_out(int _c)
        {
            if (_c != EC_SYM_MAX)
            {
                /*No further carry propagation possible, flush buffer.*/
                int carry;
                carry = _c >> EC_SYM_BITS;

                /*Don't output a byte on the first write.
                  This compare should be taken care of by branch-prediction thereafter.*/
                if (this.rem >= 0)
                {
                    this.error |= write_byte((uint)(this.rem + carry));
                }

                if (this.ext > 0)
                {
                    uint sym;
                    sym = (EC_SYM_MAX + (uint)carry) & EC_SYM_MAX;
                    do this.error |= write_byte(sym);
                    while (--(this.ext) > 0);
                }

                this.rem = (int)((uint)_c & EC_SYM_MAX);
            }
            else
            {
                this.ext++;
            }
        }

        internal void enc_normalize()
        {
            /*If the range is too small, output some bits and rescale it.*/
            while (this.rng <= EC_CODE_BOT)
            {
                enc_carry_out((int)(this.val >> (int)EC_CODE_SHIFT));
                /*Move the next-to-high-order symbol into the high-order position.*/
                this.val = (this.val << EC_SYM_BITS) & (EC_CODE_TOP - 1);
                this.rng = this.rng << EC_SYM_BITS;
                this.nbits_total += EC_SYM_BITS;
            }
        }

        internal void enc_init(byte[] _buf, int buf_ptr, uint _size)
        {
            this.buf = _buf;
            this.buf_ptr = buf_ptr;
            this.end_offs = 0;
            this.end_window = 0;
            this.nend_bits = 0;
            /*This is the offset from which ec_tell() will subtract partial bits.*/
            this.nbits_total = EC_CODE_BITS + 1;
            this.offs = 0;
            this.rng = EC_CODE_TOP;
            this.rem = -1;
            this.val = 0;
            this.ext = 0;
            this.storage = _size;
            this.error = 0;
        }

        internal void encode(uint _fl, uint _fh, uint _ft)
        {
            uint r;
            r = this.rng / _ft;
            if (_fl > 0)
            {
                this.val += this.rng - (r * (_ft - _fl));
                this.rng = (r * (_fh - _fl));
            }
            else
            {
                this.rng -= (r * (_ft - _fh));
            }
            
            enc_normalize();
        }

        internal void encode_bin(uint _fl, uint _fh, uint _bits)
        {
            uint r;
            r = this.rng >> (int)_bits;
            if (_fl > 0)
            {
                this.val += this.rng - (r * ((1U << (int)_bits) - _fl));
                this.rng = (r * (_fh - _fl));
            }
            else this.rng -= (r * ((1U << (int)_bits) - _fh));
            enc_normalize();
        }

        /*The probability of having a "one" is 1/(1<<_logp).*/
        internal void enc_bit_logp(int _val, uint _logp)
        {
            uint r;
            uint s;
            uint l;
            r = this.rng;
            l = this.val;
            s = r >> (int)_logp;
            r -= s;
            if (_val != 0)
            {
                this.val = l + r;
            }

            this.rng = _val != 0 ? s : r;
            enc_normalize();
        }

        internal void enc_icdf(int _s, byte[] _icdf, uint _ftb)
        {
            uint r;
            r = this.rng >> (int)_ftb;
            if (_s > 0)
            {
                this.val += this.rng - (r * _icdf[_s - 1]);
                this.rng = (r * (uint)(_icdf[_s - 1] - _icdf[_s]));
            }
            else
            {
                this.rng -= (r * _icdf[_s]);
            }
            enc_normalize();
        }

        internal void enc_icdf(int _s, byte[] _icdf, int icdf_ptr, uint _ftb)
        {
            uint r;
            r = this.rng >> (int)_ftb;
            if (_s > 0)
            {
                this.val += this.rng - (r * _icdf[icdf_ptr + _s - 1]);
                this.rng = (r * (uint)(_icdf[icdf_ptr + _s - 1] - _icdf[icdf_ptr + _s]));
            }
            else
            {
                this.rng -= (r * _icdf[icdf_ptr + _s]);
            }
            enc_normalize();
        }

        internal void enc_uint(uint _fl, uint _ft)
        {
            uint ft;
            uint fl;
            int ftb;
            /*In order to optimize EC_ILOG(), it is undefined for the value 0.*/
            Inlines.OpusAssert(_ft > 1);
            _ft--;
            ftb = Inlines.EC_ILOG(_ft);
            if (ftb > EC_UINT_BITS)
            {
                ftb -= EC_UINT_BITS;
                ft = (_ft >> ftb) + 1;
                fl = (uint)(_fl >> ftb);
                encode(fl, fl + 1, ft);
                enc_bits(_fl & (((uint)1 << ftb) - 1U), (uint)ftb);
            }
            else encode(_fl, _fl + 1, _ft + 1);
        }

        internal void enc_bits(uint _fl, uint _bits)
        {
            uint window;
            int used;
            window = this.end_window;
            used = this.nend_bits;
            Inlines.OpusAssert(_bits > 0);

            if (used + _bits > EC_WINDOW_SIZE)
            {
                do
                {
                    this.error |= write_byte_at_end((uint)window & EC_SYM_MAX);
                    window >>= EC_SYM_BITS;
                    used -= EC_SYM_BITS;
                }
                while (used >= EC_SYM_BITS);
            }

            window |= (uint)_fl << used;
            used += (int)_bits;
            this.end_window = window;
            this.nend_bits = used;
            this.nbits_total += (int)_bits;
        }

        internal void enc_patch_initial_bits(uint _val, uint _nbits)
        {
            int shift;
            uint mask;
            Inlines.OpusAssert(_nbits <= EC_SYM_BITS);
            shift = EC_SYM_BITS - (int)_nbits;
            mask = ((1U << (int)_nbits) - 1) << shift;

            if (this.offs > 0)
            {
                /*The first byte has been finalized.*/
                this.buf[buf_ptr] = (byte)((this.buf[buf_ptr] & ~mask) | _val << shift);
            }
            else if (this.rem >= 0)
            {
                /*The first byte is still awaiting carry propagation.*/
                this.rem = (int)(((uint)this.rem & ~mask) | _val) << shift;
            }
            else if (this.rng <= (EC_CODE_TOP >> (int)_nbits))
            {
                /*The renormalization loop has never been run.*/
                this.val = (this.val & ~((uint)mask << (int)EC_CODE_SHIFT)) |
                 (uint)_val << (int)(EC_CODE_SHIFT + shift);
            }
            else
            {
                /*The encoder hasn't even encoded _nbits of data yet.*/
                this.error = -1;
            }
        }

        internal void enc_shrink(uint _size)
        {
            Inlines.OpusAssert(this.offs + this.end_offs <= _size);
            //(memmove(this.buf + _size - this.end_offs, this.buf + this.storage - this.end_offs, this.end_offs * sizeof(*(dst))))
            Arrays.MemMove<byte>(this.buf, buf_ptr + (int)_size - (int)this.end_offs, buf_ptr + (int)this.storage - (int)this.end_offs, (int)this.end_offs);
            this.storage = _size;
        }

        internal uint range_bytes()
        {
            return this.offs;
        }

        internal int get_error()
        {
            return this.error;
        }

        /// <summary>
        /// Returns the number of bits "used" by the encoded or decoded symbols so far.
        /// This same number can be computed in either the encoder or the decoder, and is
        /// suitable for making coding decisions.
        /// This will always be slightly larger than the exact value (e.g., all
        /// rounding error is in the positive direction).
        /// </summary>
        /// <returns>The number of bits.</returns>
        internal int tell()
        {
            int returnVal = this.nbits_total - Inlines.EC_ILOG(this.rng);
            return returnVal;
        }

        private static readonly uint[] correction = {35733, 38967, 42495, 46340, 50535, 55109, 60097, 65535};

        /// <summary>
        /// This is a faster version of ec_tell_frac() that takes advantage
        /// of the low(1/8 bit) resolution to use just a linear function
        /// followed by a lookup to determine the exact transition thresholds.
        /// </summary>
        /// <returns></returns>
        internal uint tell_frac()
        {
            int nbits;
            int r;
            int l;
            uint b;
            nbits = this.nbits_total << EntropyCoder.BITRES;
            l = Inlines.EC_ILOG(this.rng);
            r = (int)(this.rng >> (l - 16));
            b = (uint)((r >> 12) - 8);
            b += (r > correction[b] ? 1u : 0);
            l = (int)((l << 3) + b);
            return (uint)(nbits - l);
        }

        internal void enc_done()
        {
            uint window;
            int used;
            uint msk;
            uint end;
            int l;
            /*We output the minimum number of bits that ensures that the symbols encoded
               thus far will be decoded correctly regardless of the bits that follow.*/
            l = EC_CODE_BITS - Inlines.EC_ILOG(this.rng);
            msk = (EC_CODE_TOP - 1) >> l;
            end = (this.val + msk) & ~msk;

            if ((end | msk) >= this.val + this.rng)
            {
                l++;
                msk >>= 1;
                end = (this.val + msk) & ~msk;
            }

            while (l > 0)
            {
                enc_carry_out((int)(end >> (int)EC_CODE_SHIFT));
                end = (end << EC_SYM_BITS) & (EC_CODE_TOP - 1);
                l -= EC_SYM_BITS;
            }

            /*If we have a buffered byte flush it into the output buffer.*/
            if (this.rem >= 0 || this.ext > 0)
            {
                enc_carry_out(0);
            }

            /*If we have buffered extra bits, flush them as well.*/
            window = this.end_window;
            used = this.nend_bits;

            while (used >= EC_SYM_BITS)
            {
                this.error |= write_byte_at_end((uint)window & EC_SYM_MAX);
                window >>= EC_SYM_BITS;
                used -= EC_SYM_BITS;
            }

            /*Clear any excess space and add any remaining extra bits to the last byte.*/
            if (this.error == 0)
            {
                Arrays.MemSetWithOffset<byte>(this.buf, 0, buf_ptr + (int)this.offs, (int)this.storage - (int)this.offs - (int)this.end_offs);
                if (used > 0)
                {
                    /*If there's no range coder data at all, give up.*/
                    if (this.end_offs >= this.storage)
                    {
                        this.error = -1;
                    }
                    else
                    {
                        l = -l;
                        /*If we've busted, don't add too many extra bits to the last byte; it
                           would corrupt the range coder data, and that's more important.*/
                        if (this.offs + this.end_offs >= this.storage && l < used)
                        {
                            window = window & ((1U << l) - 1);
                            this.error = -1;
                        }

                        this.buf[buf_ptr + this.storage - this.end_offs - 1] |= (byte)window;
                    }
                }
            }
        }
    }
}

Q:

Usercontrol properties in Styles

I have a usercontrol that expose a public property like this :
public Double ButtonImageHeight
{
   get { return imgButtonImage.Height; }
   set { imgButtonImage.Height = value; }
}

when I use that control, I want to be able to set that property throught a Style like that :
<Style x:Key="MyButtonStyle" TargetType="my:CustomButtonUserControl" >
   <Setter Property="ButtonImageHeight" Value="100" />
</Style>

What am I doing wrong?
Thanks

A:

thanks Matt,  I just found it myself but you were absolutely right... here's the exact code I used in case it can help someone else (all the examples I found were on WPF, silverlight is just slightly different) :
public static readonly DependencyProperty ButtonImageHeightProperty = DependencyProperty.Register("ButtonImageHeight", typeof(Double), typeof(CustomButtonUserControl),new PropertyMetadata(ButtonImageHeight_PropertyChanged ));

public Double ButtonImageHeight
{
   get { return (Double)GetValue(ButtonImageHeightProperty); }
   set { SetValue(ButtonImageHeightProperty, value); }
 }

private static void ButtonImageHeight_PropertyChanged(DependencyObject source, DependencyPropertyChangedEventArgs e)
{
   ((CustomButtonUserControl)source).imgButtonImage.Height = (Double)e.NewValue;
}

A:

The property needs to be a dependency property in order to support styles.

Q:

Convert from std::string to DWORD

I have a simple problem with a conversion:  
std::string str = "0xC0A80A02"

and I need to convert it to DWORD.
I searched on the web and found some solution but none seems to work.
try1:  
DWORD m_dwIP = atol(str.c_str());

try2:  
std::istringstream ss(str.c_str());
ss >> m_dwIP;

try3:  
sscanf (str.c_str(),"%u",str,&m_dwIP);

Note the string stores the value in hexa .  
Thanks,
Gabriel

A:

Assuming sizeof(DWORD) == sizeof(unsigned long), this should do:
#include <cstdlib>
DWORD m_dwIP = std::strtoul(str.c_str(), NULL, 16);

See http://www.cplusplus.com/reference/clibrary/cstdlib/strtoul/.
Note that this is usable for both C and C++ (strip of the std:: and c_str() and change <cstdlib> to <stdlib.h> but this should be pretty obvious).

A:

istringstream will work fine, just strip off the 0x prefix and use the std::hex formatter:
  std::string str = "0xC0A80A02";
  unsigned int m_dwIP;

  std::istringstream ss(&str[2]);
  ss >> std::hex >> m_dwIP;

  std::cout << std::hex << m_dwIP << "\n";

Outputs c0a80a02.

